// v23.xx (gfx40), HIS ORDER 2026-10-12 (the graphics program, item 15, TV readability): HUD SIZE LARGE FOR TV GROWS THE WORLD TEXT.
// The Settings row HUD SIZE (CFG.hudTv) was there with nothing reading it. LARGE FOR TV (1) now draws the words over the world
// (nameplates, party tags, damage numbers, the loot and kill labels) 1.3 times larger, so they read from a sofa: for the length of
// the two world text passes FS hands out every size grown 1.3 times (gfxTvFS), and the plates, measured from the font, grow with
// them about the same anchors. FS is handed back in finally. The HUD itself (status icons, belt, use bar, the boss plate) is not
// touched: the UI program owns it, and its boxes are pinned by this build's check. STANDARD (0, the default) is unchanged.
function gfxTvFS(base){
  return function(spec){ return base(String(spec).replace(/([\d.]+)px/,function(m,n){ return (Math.round(parseFloat(n)*1.3*100)/100)+'px'; })); };
}
var GFXWT=null;

